import functools


_registry = {}


class Counter:
    def __init__(self, name, description=""):
        self.name = name
        self.description = description
        self._value = 0

    def inc(self, amount=1):
        self._value += amount

    def value(self):
        return self._value

    def reset(self):
        self._value = 0

    def to_dict(self):
        return {"name": self.name, "type": "counter", "value": self._value}


class Gauge:
    def __init__(self, name, description=""):
        self.name = name
        self.description = description
        self._value = 0

    def set(self, value):
        self._value = value

    def inc(self, amount=1):
        self._value += amount

    def dec(self, amount=1):
        self._value -= amount

    def value(self):
        return self._value

    def to_dict(self):
        return {"name": self.name, "type": "gauge", "value": self._value}


class Histogram:
    def __init__(self, name, description="", buckets=None):
